import importlib
import six
from abc import ABCMeta, abstractmethod


class Command(object):

    def __init__(self, executor=None, cmd=None):
        self._executor = executor
        self._cmd = cmd

    def execute(self):
        self._executor.execute(cmd=self._cmd)


class InjectCommand(Command):
    def __init__(self, executor=None, cmd=None):
        super(InjectCommand, self).__init__(executor=executor, cmd=cmd)


class InjectCommandSetFactory(object):

    def __init__(self, version, executor=None):
        self._version = version.replace(".", "_")
        self._executor = executor

    def create(self):
        package = importlib.import_module("taf.ue.plugin.mtk.commands.inject_commands")
        return [InjectCommand(self._executor, command) for command in package.commands]


@six.add_metaclass(ABCMeta)
class SetDefaultFilter(object):

    def __init__(self, filter_name=None):
        self._filter_name = filter_name

    @property
    def filter_name(self):
        return self._filter_name

    @abstractmethod
    def execute(self):
        pass


@six.add_metaclass(ABCMeta)
class GetPlatformInfo(object):

    @abstractmethod
    def execute(self):
        pass


@six.add_metaclass(ABCMeta)
class PortsReady(object):
    @abstractmethod
    def execute(self):
        pass
